pragma solidity ^0.8.7; interface IERC20 { event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address to, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom(address from, address to, uint256 amount) external returns (bool); } interface IERC20Metadata is IERC20 { function name() external view returns (string memory); function symbol() external view returns (string memory); function decimals() external view returns (uint8); } interface IERC20Permit { function permit( address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s ) external; function nonces(address owner) external view returns (uint256); function DOMAIN_SEPARATOR() external view returns (bytes32); } library Address { function isContract(address account) internal view returns (bool) { return account.code.length > 0; } function sendValue(address payable recipient, uint256 amount) internal { require(address(this).balance >= amount, "Address: insufficient balance"); (bool success, ) = recipient.call{value: amount}(""); require(success, "Address: unable to send value, recipient may have reverted"); } function functionCall(address target, bytes memory data) internal returns (bytes memory) { return functionCallWithValue(target, data, 0, "Address: low-level call failed"); } function functionCall( address target, bytes memory data, string memory errorMessage ) internal returns (bytes memory) { return functionCallWithValue(target, data, 0, errorMessage); } function functionCallWithValue(address target, bytes memory data, uint256 value) internal returns (bytes memory) { return functionCallWithValue(target, data, value, "Address: low-level call with value failed"); } function functionCallWithValue( address target, bytes memory data, uint256 value, string memory errorMessage ) internal returns (bytes memory) { require(address(this).balance >= value, "Address: insufficient balance for call"); (bool success, bytes memory returndata) = target.call{value: value}(data); return verifyCallResultFromTarget(target, success, returndata, errorMessage); } function functionStaticCall(address target, bytes memory data) internal view returns (bytes memory) { return functionStaticCall(target, data, "Address: low-level static call failed"); } function functionStaticCall( address target, bytes memory data, string memory errorMessage ) internal view returns (bytes memory) { (bool success, bytes memory returndata) = target.staticcall(data); return verifyCallResultFromTarget(target, success, returndata, errorMessage); } function functionDelegateCall(address target, bytes memory data) internal returns (bytes memory) { return functionDelegateCall(target, data, "Address: low-level delegate call failed"); } function functionDelegateCall( address target, bytes memory data, string memory errorMessage ) internal returns (bytes memory) { (bool success, bytes memory returndata) = target.delegatecall(data); return verifyCallResultFromTarget(target, success, returndata, errorMessage); } function verifyCallResultFromTarget( address target, bool success, bytes memory returndata, string memory errorMessage ) internal view returns (bytes memory) { if (success) { if (returndata.length == 0) { require(isContract(target), "Address: call to non-contract"); } return returndata; } else { _revert(returndata, errorMessage); } } function verifyCallResult( bool success, bytes memory returndata, string memory errorMessage ) internal pure returns (bytes memory) { if (success) { return returndata; } else { _revert(returndata, errorMessage); } } function _revert(bytes memory returndata, string memory errorMessage) private pure { if (returndata.length > 0) { assembly { let returndata_size := mload(returndata) revert(add(32, returndata), returndata_size) } } else { revert(errorMessage); } } } library SafeERC20 { using Address for address; function safeTransfer(IERC20 token, address to, uint256 value) internal { _callOptionalReturn(token, abi.encodeWithSelector(token.transfer.selector, to, value)); } function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal { _callOptionalReturn(token, abi.encodeWithSelector(token.transferFrom.selector, from, to, value)); } function safeApprove(IERC20 token, address spender, uint256 value) internal { require( (value == 0) || (token.allowance(address(this), spender) == 0), "SafeERC20: approve from non-zero to non-zero allowance" ); _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, value)); } function safeIncreaseAllowance(IERC20 token, address spender, uint256 value) internal { uint256 oldAllowance = token.allowance(address(this), spender); _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, oldAllowance + value)); } function safeDecreaseAllowance(IERC20 token, address spender, uint256 value) internal { unchecked { uint256 oldAllowance = token.allowance(address(this), spender); require(oldAllowance >= value, "SafeERC20: decreased allowance below zero"); _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, oldAllowance - value)); } } function forceApprove(IERC20 token, address spender, uint256 value) internal { bytes memory approvalCall = abi.encodeWithSelector(token.approve.selector, spender, value); if (!_callOptionalReturnBool(token, approvalCall)) { _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, 0)); _callOptionalReturn(token, approvalCall); } } function safePermit( IERC20Permit token, address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s ) internal { uint256 nonceBefore = token.nonces(owner); token.permit(owner, spender, value, deadline, v, r, s); uint256 nonceAfter = token.nonces(owner); require(nonceAfter == nonceBefore + 1, "SafeERC20: permit did not succeed"); } function _callOptionalReturn(IERC20 token, bytes memory data) private { bytes memory returndata = address(token).functionCall(data, "SafeERC20: low-level call failed"); require(returndata.length == 0 || abi.decode(returndata, (bool)), "SafeERC20: ERC20 operation did not succeed"); } function _callOptionalReturnBool(IERC20 token, bytes memory data) private returns (bool) { (bool success, bytes memory returndata) = address(token).call(data); return success && (returndata.length == 0 || abi.decode(returndata, (bool))) && Address.isContract(address(token)); } } abstract contract Context { function _msgSender() internal view virtual returns (address) { return msg.sender; } function _msgData() internal view virtual returns (bytes calldata) { return msg.data; } function _contextSuffixLength() internal view virtual returns (uint256) { return 0; } } contract InsureDAOERC20 is Context, IERC20, IERC20Metadata { mapping(address => uint256) private _balances; mapping(address => mapping(address => uint256)) private _allowances; uint256 private _totalSupply; bool tokenInitialized; string private _name = "InsureDAO LP Token"; string private _symbol = "iLP"; uint8 private _decimals = 18; constructor() {} function initializeToken( string memory name_, string memory symbol_, uint8 decimals_ ) internal { assert(!tokenInitialized); tokenInitialized = true; _name = name_; _symbol = symbol_; _decimals = decimals_; } function name() public view virtual override returns (string memory) { return _name; } function symbol() public view virtual override returns (string memory) { return _symbol; } function decimals() public view virtual override returns (uint8) { return _decimals; } function totalSupply() public view virtual override returns (uint256) { return _totalSupply; } function balanceOf(address account) public view virtual override returns (uint256) { return _balances[account]; } function transfer(address recipient, uint256 amount) public virtual override returns (bool) { _transfer(_msgSender(), recipient, amount); return true; } function allowance(address owner, address spender) public view virtual override returns (uint256) { return _allowances[owner][spender]; } function approve(address spender, uint256 amount) public virtual override returns (bool) { _approve(_msgSender(), spender, amount); return true; } function transferFrom( address sender, address recipient, uint256 amount ) public virtual override returns (bool) { _transfer(sender, recipient, amount); uint256 currentAllowance = _allowances[sender][_msgSender()]; require( currentAllowance >= amount, "ERC20: transfer amount exceeds allowance" ); _approve(sender, _msgSender(), currentAllowance - amount); return true; } function increaseAllowance(address spender, uint256 addedValue) public virtual returns (bool) { _approve( _msgSender(), spender, _allowances[_msgSender()][spender] + addedValue ); return true; } function decreaseAllowance(address spender, uint256 subtractedValue) public virtual returns (bool) { uint256 currentAllowance = _allowances[_msgSender()][spender]; require( currentAllowance >= subtractedValue, "ERC20: decreased allowance below zero" ); _approve(_msgSender(), spender, currentAllowance - subtractedValue); return true; } function _transfer( address sender, address recipient, uint256 amount ) internal virtual { require(sender != address(0), "ERC20: transfer from the zero address"); require(recipient != address(0), "ERC20: transfer to the zero address"); _beforeTokenTransfer(sender, recipient, amount); uint256 senderBalance = _balances[sender]; require( senderBalance >= amount, "ERC20: transfer amount exceeds balance" ); _balances[sender] = senderBalance - amount; _balances[recipient] += amount; emit Transfer(sender, recipient, amount); _afterTokenTransfer(sender, recipient, amount); } function _mint(address account, uint256 amount) internal virtual { require(account != address(0), "ERC20: mint to the zero address"); _beforeTokenTransfer(address(0), account, amount); _totalSupply += amount; _balances[account] += amount; emit Transfer(address(0), account, amount); _afterTokenTransfer(address(0), account, amount); } function _burn(address account, uint256 amount) internal virtual { require(account != address(0), "ERC20: burn from the zero address"); _beforeTokenTransfer(account, address(0), amount); uint256 accountBalance = _balances[account]; require(accountBalance >= amount, "ERC20: burn amount exceeds balance"); _balances[account] = accountBalance - amount; _totalSupply -= amount; emit Transfer(account, address(0), amount); _afterTokenTransfer(account, address(0), amount); } function _approve( address owner, address spender, uint256 amount ) internal virtual { require(owner != address(0), "ERC20: approve from the zero address"); require(spender != address(0), "ERC20: approve to the zero address"); _allowances[owner][spender] = amount; emit Approval(owner, spender, amount); } function _beforeTokenTransfer( address from, address to, uint256 amount ) internal virtual {} function _afterTokenTransfer( address from, address to, uint256 amount ) internal virtual {} } interface ICDSTemplate { function compensate(uint256) external returns (uint256 _compensated); function defund(uint256 _amount) external; } abstract contract IParameters { function setVault(address _token, address _vault) external virtual; function setLockup(address _address, uint256 _target) external virtual; function setGrace(address _address, uint256 _target) external virtual; function setMinDate(address _address, uint256 _target) external virtual; function setUpperSlack(address _address, uint256 _target) external virtual; function setLowerSlack(address _address, uint256 _target) external virtual; function setWithdrawable(address _address, uint256 _target) external virtual; function setPremiumModel(address _address, address _target) external virtual; function setFeeRate(address _address, uint256 _target) external virtual; function setMaxList(address _address, uint256 _target) external virtual; function setCondition(bytes32 _reference, bytes32 _target) external virtual; function getOwner() external view virtual returns (address); function getVault(address _token) external view virtual returns (address); function getPremium( uint256 _amount, uint256 _term, uint256 _totalLiquidity, uint256 _lockedAmount, address _target ) external view virtual returns (uint256); function getFeeRate(address _target) external view virtual returns (uint256); function getUpperSlack(address _target) external view virtual returns (uint256); function getLowerSlack(address _target) external view virtual returns (uint256); function getLockup(address _target) external view virtual returns (uint256); function getWithdrawable(address _target) external view virtual returns (uint256); function getGrace(address _target) external view virtual returns (uint256); function getMinDate(address _target) external view virtual returns (uint256); function getMaxList(address _target) external view virtual returns (uint256); function getCondition(bytes32 _reference) external view virtual returns (bytes32); } interface IRegistry { function isListed(address _market) external view returns (bool); function getCDS(address _address) external view returns (address); function confirmExistence(address _template, address _target) external view returns (bool); function setFactory(address _factory) external; function supportMarket(address _market) external; function setExistence(address _template, address _target) external; function setCDS(address _address, address _cds) external; } interface IUniversalMarket { function initialize( string calldata _metaData, uint256[] calldata _conditions, address[] calldata _references ) external; function setPaused(bool state) external; function changeMetadata(string calldata _metadata) external; } interface IVault { function addValueBatch( uint256 _amount, address _from, address[2] memory _beneficiaries, uint256[2] memory _shares ) external returns (uint256[2] memory _allocations); function addValue( uint256 _amount, address _from, address _attribution ) external returns (uint256 _attributions); function withdrawValue(uint256 _amount, address _to) external returns (uint256 _attributions); function transferValue(uint256 _amount, address _destination) external returns (uint256 _attributions); function withdrawAttribution(uint256 _attribution, address _to) external returns (uint256 _retVal); function withdrawAllAttribution(address _to) external returns (uint256 _retVal); function transferAttribution(uint256 _amount, address _destination) external; function attributionOf(address _target) external view returns (uint256); function underlyingValue(address _target) external view returns (uint256); function attributionValue(uint256 _attribution) external view returns (uint256); function utilize() external returns (uint256 _amount); function token() external returns (address); function borrowValue(uint256 _amount, address _to) external; function offsetDebt(uint256 _amount, address _target) external returns (uint256 _attributions); function repayDebt(uint256 _amount, address _target) external; function debts(address _debtor) external view returns (uint256); function transferDebt(uint256 _amount) external; function withdrawRedundant(address _token, address _to) external; function setController(address _controller) external; function setKeeper(address _keeper) external; } contract CDSTemplate is InsureDAOERC20, ICDSTemplate, IUniversalMarket { event Deposit(address indexed depositor, uint256 amount, uint256 mint); event Fund(address indexed depositor, uint256 amount, uint256 attribution); event Defund( address indexed depositor, uint256 amount, uint256 attribution ); event WithdrawRequested( address indexed withdrawer, uint256 amount, uint256 time ); event Withdraw(address indexed withdrawer, uint256 amount, uint256 retVal); event Compensated(address indexed index, uint256 amount); event Paused(bool paused); event MetadataChanged(string metadata); bool public initialized; bool public paused; string public metadata; IParameters public parameters; IRegistry public registry; IVault public vault; uint256 public surplusPool; uint256 public crowdPool; uint256 public constant MAGIC_SCALE_1E6 = 1e6; struct Withdrawal { uint256 timestamp; uint256 amount; } mapping(address => Withdrawal) public withdrawalReq; modifier onlyOwner() { require( msg.sender == parameters.getOwner(), "ERROR: ONLY_OWNER" ); _; } constructor() { initialized = true; } function initialize( string calldata _metaData, uint256[] calldata _conditions, address[] calldata _references ) external override{ require( initialized == false && bytes(_metaData).length > 0 && _references[0] != address(0) && _references[1] != address(0) && _references[2] != address(0), "ERROR: INITIALIZATION_BAD_CONDITIONS" ); initialized = true; string memory _name = "InsureDAO-CDS"; string memory _symbol = "iCDS"; uint8 _decimals = IERC20Metadata(_references[0]).decimals(); initializeToken(_name, _symbol, _decimals); parameters = IParameters(_references[2]); vault = IVault(parameters.getVault(_references[0])); registry = IRegistry(_references[1]); metadata = _metaData; } function deposit(uint256 _amount) external returns (uint256 _mintAmount) { require(paused == false, "ERROR: PAUSED"); require(_amount > 0, "ERROR: DEPOSIT_ZERO"); uint256 _liquidity = vault.attributionValue(crowdPool); uint256 _supply = totalSupply(); crowdPool += vault.addValue(_amount, msg.sender, address(this)); if (_supply > 0 && _liquidity > 0) { _mintAmount = (_amount * _supply) / _liquidity; } else if (_supply > 0 && _liquidity == 0) { _mintAmount = _amount * _supply; } else { _mintAmount = _amount; } emit Deposit(msg.sender, _amount, _mintAmount); _mint(msg.sender, _mintAmount); } function fund(uint256 _amount) external { require(paused == false, "ERROR: PAUSED"); uint256 _attribution = vault.addValue( _amount, msg.sender, address(this) ); surplusPool += _attribution; emit Fund(msg.sender, _amount, _attribution); } function defund(uint256 _amount) external override onlyOwner { require(paused == false, "ERROR: PAUSED"); uint256 _attribution = vault.withdrawValue(_amount, msg.sender); surplusPool -= _attribution; emit Defund(msg.sender, _amount, _attribution); } function requestWithdraw(uint256 _amount) external { uint256 _balance = balanceOf(msg.sender); require(_balance >= _amount, "ERROR: REQUEST_EXCEED_BALANCE"); require(_amount > 0, "ERROR: REQUEST_ZERO"); withdrawalReq[msg.sender].timestamp = block.timestamp; withdrawalReq[msg.sender].amount = _amount; emit WithdrawRequested(msg.sender, _amount, block.timestamp); } function withdraw(uint256 _amount) external returns (uint256 _retVal) { Withdrawal memory request = withdrawalReq[msg.sender]; require(paused == false, "ERROR: PAUSED"); require( request.timestamp + parameters.getLockup(msg.sender) < block.timestamp, "ERROR: WITHDRAWAL_QUEUE" ); require( request.timestamp + parameters.getLockup(msg.sender) + parameters.getWithdrawable(msg.sender) > block.timestamp, "ERROR: WITHDRAWAL_NO_ACTIVE_REQUEST" ); require( request.amount >= _amount, "ERROR: WITHDRAWAL_EXCEEDED_REQUEST" ); require(_amount > 0, "ERROR: WITHDRAWAL_ZERO"); _retVal = (vault.attributionValue(crowdPool) * _amount) / totalSupply(); request.amount -= _amount; _burn(msg.sender, _amount); crowdPool -= vault.withdrawValue(_retVal, msg.sender); emit Withdraw(msg.sender, _amount, _retVal); } function compensate(uint256 _amount) external override returns (uint256 _compensated) { require(registry.isListed(msg.sender)); uint256 _available = vault.underlyingValue(address(this)); uint256 _crowdAttribution = crowdPool; uint256 _surplusAttribution = surplusPool; uint256 _attributionLoss; if (_available >= _amount) { _compensated = _amount; _attributionLoss = vault.transferValue(_amount, msg.sender); emit Compensated(msg.sender, _amount); } else { _compensated = _available; _attributionLoss = vault.transferValue(_available, msg.sender); emit Compensated(msg.sender, _available); } uint256 _crowdPoolLoss = (_crowdAttribution * _attributionLoss) / (_crowdAttribution + _surplusAttribution); crowdPool -= _crowdPoolLoss; surplusPool -= (_attributionLoss - _crowdPoolLoss); } function totalLiquidity() public view returns (uint256 _balance) { return vault.underlyingValue(address(this)); } function rate() external view returns (uint256) { if (totalSupply() > 0) { return (vault.attributionValue(crowdPool) * MAGIC_SCALE_1E6) / totalSupply(); } else { return 0; } } function valueOfUnderlying(address _owner) public view returns (uint256) { uint256 _balance = balanceOf(_owner); if (_balance == 0) { return 0; } else { return _balance * vault.attributionValue(crowdPool) / totalSupply(); } } function changeMetadata(string calldata _metadata) external override onlyOwner { metadata = _metadata; emit MetadataChanged(_metadata); } function setPaused(bool _state) external override onlyOwner { if (paused != _state) { paused = _state; emit Paused(_state); } } function _beforeTokenTransfer( address from, address to, uint256 amount ) internal virtual override { super._beforeTokenTransfer(from, to, amount); if (from != address(0)) { uint256 _after = balanceOf(from) - amount; if (_after < withdrawalReq[from].amount) { withdrawalReq[from].amount = _after; } } } } interface IFactory { function approveTemplate( IUniversalMarket _template, bool _approval, bool _isOpen, bool _duplicate ) external; function approveReference( IUniversalMarket _template, uint256 _slot, address _target, bool _approval ) external; function setCondition( IUniversalMarket _template, uint256 _slot, uint256 _target ) external; function createMarket( IUniversalMarket _template, string memory _metaData, uint256[] m